package com.example.ui.util

import com.example.model.AppLanguage

object LanguageStrings {

    fun get(key: String, language: AppLanguage = AppLanguage.HINGLISH): String {
        val entry = map[key] ?: return key
        return when (language) {
            AppLanguage.HINGLISH -> entry.hinglish
            AppLanguage.HINDI -> entry.hindi
            AppLanguage.GUJARATI -> entry.gujarati
            AppLanguage.ENGLISH -> entry.english
        }
    }

    fun get(key: String, langCode: String): String {
        val appLang = when (langCode.lowercase()) {
            "hi", "hindi" -> AppLanguage.HINDI
            "gu", "gujarati" -> AppLanguage.GUJARATI
            "en", "english" -> AppLanguage.ENGLISH
            else -> AppLanguage.HINGLISH
        }
        return get(key, appLang)
    }

    fun format(key: String, language: AppLanguage = AppLanguage.HINGLISH, vararg args: Any): String {
        return try {
            String.format(get(key, language), *args)
        } catch (e: Exception) {
            get(key, language)
        }
    }

    fun format(key: String, langCode: String, vararg args: Any): String {
        return try {
            String.format(get(key, langCode), *args)
        } catch (e: Exception) {
            get(key, langCode)
        }
    }

    private data class Trans(
        val hinglish: String,
        val hindi: String,
        val gujarati: String,
        val english: String
    )

