        "bg_opened_app_info" to Trans("Seedha screen nahi khuli. App Info khuli hai - wahan Battery > Unrestricted chunein.", "सीधी स्क्रीन नहीं खुली। ऐप इन्फो खुली है - वहाँ बैटरी > अनरिस्ट्रिक्टेड चुनें।", "સીધી સ્ક્રીન ખુલી નથી. ઍપ ઇન્ફો ખુલી છે - ત્યાં બેટરી > અનરિસ્ટ્રિક્ટેડ પસંદ કરો.", "Couldn't open the exact screen. App Info opened - choose Battery > Unrestricted there."),
        "bg_cannot_open" to Trans("Settings nahi khul payi. Phone ki Settings me upar likha raasta follow karein.", "सेटिंग्स नहीं खुल पाई। फोन की सेटिंग्स में ऊपर लिखा रास्ता अपनाएँ।", "સેટિંગ્સ ખુલી શકી નથી. ફોનની સેટિંગ્સમાં ઉપર લખેલો રસ્તો અનુસરો.", "Couldn't open Settings. Please follow the path shown above in your phone's Settings."),
        "bg_battery_samsung" to Trans("Settings > Apps > is app ko chunein > Battery > Unrestricted", "सेटिंग्स > ऐप्स > इस ऐप को चुनें > बैटरी > अनरिस्ट्रिक्टेड", "સેટિંગ્સ > ઍપ્સ > આ ઍપ પસંદ કરો > બેટરી > અનરિસ્ટ્રિક્ટેડ", "Settings > Apps > select this app > Battery > Unrestricted"),
        "bg_autostart_samsung" to Trans("Settings > Battery > Background usage limits > Never auto sleeping apps > is app ko jodein", "सेटिंग्स > बैटरी > बैकग्राउंड यूसेज लिमिट्स > नेवर ऑटो स्लीपिंग ऐप्स > इस ऐप को जोड़ें", "સેટિંગ્સ > બેટરી > બેકગ્રાઉન્ડ યુસેજ લિમિટ્સ > નેવર ઓટો સ્લીપિંગ ઍપ્સ > આ ઍપ ઉમેરો", "Settings > Battery > Background usage limits > Never auto sleeping apps > add this app"),
        "bg_battery_oppo" to Trans("Settings > Battery > More battery settings > Optimize battery use > is app par Don't optimize", "सेटिंग्स > बैटरी > मोर बैटरी सेटिंग्स > ऑप्टिमाइज़ बैटरी यूज़ > इस ऐप पर Don't optimize", "સેટિંગ્સ > બેટરી > મોર બેટરી સેટિંગ્સ > ઓપ્ટિમાઇઝ બેટરી યુઝ > આ ઍપ પર Don't optimize", "Settings > Battery > More battery settings > Optimize battery use > set this app to Don't optimize"),
        "bg_autostart_oppo" to Trans("Settings > App Management > is app ko chunein > Allow auto-launch aur Allow background activity ON karein", "सेटिंग्स > ऐप मैनेजमेंट > इस ऐप को चुनें > ऑटो-लॉन्च और बैकग्राउंड एक्टिविटी चालू करें", "સેટિંગ્સ > ઍપ મેનેજમેન્ટ > આ ઍપ પસંદ કરો > ઓટો-લૉન્ચ અને બેકગ્રાઉન્ડ એક્ટિવિટી ચાલુ કરો", "Settings > App Management > select this app > turn ON Allow auto-launch and Allow background activity"),
        "bg_battery_xiaomi" to Trans("Settings > Apps > Manage apps > is app ko chunein > Battery saver > No restrictions", "सेटिंग्स > ऐप्स > मैनेज ऐप्स > इस ऐप को चुनें > बैटरी सेवर > नो रिस्ट्रिक्शन्स", "સેટિંગ્સ > ઍપ્સ > મેનેજ ઍપ્સ > આ ઍપ પસંદ કરો > બેટરી સેવર > નો રિસ્ટ્રિક્શન્સ", "Settings > Apps > Manage apps > select this app > Battery saver > No restrictions"),
        "bg_autostart_xiaomi" to Trans("Settings > Apps > Permissions > Autostart > is app ko ON karein. Recent apps me app ko neeche kheench kar lock karein.", "सेटिंग्स > ऐप्स > परमिशन्स > ऑटोस्टार्ट > इस ऐप को चालू करें। रीसेंट ऐप्स में ऐप को नीचे खींचकर लॉक करें।", "સેટિંગ્સ > ઍપ્સ > પરમિશન્સ > ઓટોસ્ટાર્ટ > આ ઍપ ચાલુ કરો. રીસેન્ટ ઍપ્સમાં ઍપને નીચે ખેંચીને લૉક કરો.", "Settings > Apps > Permissions > Autostart > turn this app ON. In Recent apps, pull the app down to lock it."),
        "bg_battery_vivo" to Trans("Settings > Battery > Background power consumption management > is app ko High background power consumption ki permission dein", "सेटिंग्स > बैटरी > बैकग्राउंड पावर कंजम्पशन मैनेजमेंट > इस ऐप को हाई बैकग्राउंड पावर कंजम्पशन की अनुमति दें", "સેટિંગ્સ > બેટરી > બેકગ્રાઉન્ડ પાવર કન્ઝમ્પ્શન મેનેજમેન્ટ > આ ઍપને હાઈ બેકગ્રાઉન્ડ પાવર કન્ઝમ્પ્શનની મંજૂરી આપો", "Settings > Battery > Background power consumption management > allow High background power consumption for this app"),
        "bg_autostart_vivo" to Trans("Settings > Apps > Autostart ya iManager > App manager > Autostart me is app ko ON karein", "सेटिंग्स > ऐप्स > ऑटोस्टार्ट या iManager > ऐप मैनेजर > ऑटोस्टार्ट में इस ऐप को चालू करें", "સેટિંગ્સ > ઍપ્સ > ઓટોસ્ટાર્ટ અથવા iManager > ઍપ મેનેજર > ઓટોસ્ટાર્ટમાં આ ઍપ ચાલુ કરો", "Settings > Apps > Autostart or iManager > App manager > turn this app ON in Autostart"),
        "bg_battery_transsion" to Trans("Settings > Battery > App battery management (ya Phone Master) > is app par No restrictions", "सेटिंग्स > बैटरी > ऐप बैटरी मैनेजमेंट (या फोन मास्टर) > इस ऐप पर नो रिस्ट्रिक्शन्स", "સેટિંગ્સ > બેટરી > ઍપ બેટરી મેનેજમેન્ટ (અથવા ફોન માસ્ટર) > આ ઍપ પર નો રિસ્ટ્રિક્શન્સ", "Settings > Battery > App battery management (or Phone Master) > set this app to No restrictions"),
        "bg_autostart_transsion" to Trans("Phone Master > Auto-start management > is app ko ON karein", "फोन मास्टर > ऑटो-स्टार्ट मैनेजमेंट > इस ऐप को चालू करें", "ફોન માસ્ટર > ઓટો-સ્ટાર્ટ મેનેજમેન્ટ > આ ઍપ ચાલુ કરો", "Phone Master > Auto-start management > turn this app ON"),
        "bg_battery_huawei" to Trans("Settings > Battery > App launch > is app par Manage manually chunein", "सेटिंग्स > बैटरी > ऐप लॉन्च > इस ऐप पर मैनेज मैन्युअली चुनें", "સેટિંગ્સ > બેટરી > ઍપ લૉન્ચ > આ ઍપ પર મેનેજ મેન્યુઅલી પસંદ કરો", "Settings > Battery > App launch > choose Manage manually for this app"),
        "bg_autostart_huawei" to Trans("Manage manually me Auto-launch, Secondary launch aur Run in background teenon ON karein", "मैनेज मैन्युअली में ऑटो-लॉन्च, सेकेंडरी लॉन्च और रन इन बैकग्राउंड तीनों चालू करें", "મેનેજ મેન્યુઅલીમાં ઓટો-લૉન્ચ, સેકન્ડરી લૉન્ચ અને રન ઇન બેકગ્રાઉન્ડ ત્રણેય ચાલુ કરો", "In Manage manually, turn ON Auto-launch, Secondary launch and Run in background"),
        "bg_battery_other" to Trans("Settings > Apps > is app ko chunein > Battery > Unrestricted (ya Don't optimize)", "सेटिंग्स > ऐप्स > इस ऐप को चुनें > बैटरी > अनरिस्ट्रिक्टेड (या Don't optimize)", "સેટિંગ્સ > ઍપ્સ > આ ઍપ પસંદ કરો > બેટરી > અનરિસ્ટ્રિક્ટેડ (અથવા Don't optimize)", "Settings > Apps > select this app > Battery > Unrestricted (or Don't optimize)"),
        "bg_autostart_other" to Trans("Agar aapke phone me Autostart ya Background activity ka option ho to is app ke liye ON karein", "अगर आपके फोन में ऑटोस्टार्ट या बैकग्राउंड एक्टिविटी का ऑप्शन हो तो इस ऐप के लिए चालू करें", "જો તમારા ફોનમાં ઓટોસ્ટાર્ટ અથવા બેકગ્રાઉન્ડ એક્ટિવિટીનો વિકલ્પ હોય તો આ ઍપ માટે ચાલુ કરો", "If your phone has an Autostart or Background activity option, turn it ON for this app"),
        "simple_mode_label" to Trans("Simple Mode", "सरल मोड", "સરળ મોડ", "Simple Mode"),
        "simple_mode_desc" to Trans("Bade buttons aur saral khata screen", "बड़े बटन और सरल खाता स्क्रीन", "મોટા બટન અને સરળ ખાતાવહી સ્ક્રીન", "Larger buttons and simplified screen"),
        "voice_entry_mic" to Trans("Voice Entry", "बोलकर एंट्री करें", "બોલીને એન્ટ્રી કરો", "Voice Entry"),
        "confirm_voice_title" to Trans("Pakka karein? (Confirm Entry)", "पुष्टि करें?", "ખાતરી કરો?", "Confirm Entry"),
